//! The hosted player on a real libmpv, with no display: no video output and no audio, playing
//! FFmpeg's own test pattern, so the protocol is checked end to end without a window.

#![cfg(feature = "libmpv")]

use std::{
    sync::{Arc, Mutex, mpsc},
    time::{Duration, Instant},
};

use anistream_model::{
    hosted::{MpvOption, PlayerEnd, PlayerOp, PlayerReport},
    playback::PlaybackId,
};
use anistream_mpv_host::{HostEvent, Player, PlayerOptions};

/// Two seconds of a synthetic test pattern and tone, generated by FFmpeg as it is read.
const PATTERN: &str = "av://lavfi:testsrc2=size=160x120:rate=25:duration=2";

struct Rig {
    player: Player,
    events: mpsc::Receiver<HostEvent>,
    _dir: tempfile::TempDir,
}

fn rig() -> Rig {
    let dir = tempfile::tempdir().unwrap();
    let (tx, events) = mpsc::channel();
    let tx = Mutex::new(tx);
    let options = PlayerOptions {
        hwdec: "no".into(),
        // A config dir of the test's own, never the viewer's mpv config.
        config_dir: None,
        cache_dir: Some(dir.path().display().to_string()),
        audio_output: Some("null".into()),
        log_level: "warn".into(),
        extra: vec![("vo".into(), "null".into())],
    };
    let player = Player::new(
        &options,
        Arc::new(move |e| {
            let _ = tx.lock().unwrap().send(e);
        }),
    )
    .expect("mpv starts");
    Rig { player, events, _dir: dir }
}

impl Rig {
    /// Every event until `done` says so, or panics after a while.
    fn until(&self, mut done: impl FnMut(&HostEvent) -> bool) -> Vec<HostEvent> {
        let deadline = Instant::now() + Duration::from_secs(15);
        let mut seen = Vec::new();
        loop {
            let left = deadline.saturating_duration_since(Instant::now());
            let event = self
                .events
                .recv_timeout(left)
                .unwrap_or_else(|_| panic!("timed out: {seen:#?}"));
            let stop = done(&event);
            seen.push(event);
            if stop {
                return seen;
            }
        }
    }

    /// Everything said in the next `wait`.
    fn quiet_for(&self, wait: Duration) -> Vec<HostEvent> {
        let deadline = Instant::now() + wait;
        let mut seen = Vec::new();
        while let Ok(e) =
            self.events.recv_timeout(deadline.saturating_duration_since(Instant::now()))
        {
            seen.push(e);
        }
        seen
    }
}

fn report(playback: PlaybackId, report: PlayerReport) -> HostEvent {
    HostEvent::Report { playback, report }
}

fn open_and_load(rig: &Rig, playback: PlaybackId) {
    rig.player
        .apply(playback, &PlayerOp::Open { fullscreen: false, speed: Some(1.0), volume: None });
    rig.player.apply(
        playback,
        &PlayerOp::Load {
            url: PATTERN.into(),
            options: vec![MpvOption {
                name: "force-media-title".into(),
                value: "Episode 1".into(),
            }],
        },
    );
}

#[test]
fn a_file_plays_through_and_is_reported_as_mpv_says_it() {
    let rig = rig();
    let one = PlaybackId::new(1);
    open_and_load(&rig, one);
    let seen = rig.until(|e| *e == report(one, PlayerReport::Ended { reason: PlayerEnd::Eof }));

    assert_eq!(seen[0], HostEvent::Opened { fullscreen: false });
    assert!(seen.contains(&report(one, PlayerReport::FileLoaded)), "{seen:#?}");
    let reported = |name: &str| {
        seen.iter().any(|e| matches!(e, HostEvent::Report { playback, report: PlayerReport::Property { name: n, .. } } if *playback == one && n == name))
    };
    for name in ["time-pos", "duration", "pause", "track-list", "video-params"] {
        assert!(reported(name), "{name} was reported: {seen:#?}");
    }
    // The duration as JSON, the way the engine parses it: a generated stream's grows as it is
    // read, so the last one said.
    let duration = seen
        .iter()
        .filter_map(|e| match e {
            HostEvent::Report { report: PlayerReport::Property { name, json }, .. }
                if name == "duration" && json != "null" =>
            {
                json.parse::<f64>().ok()
            }
            _ => None,
        })
        .next_back();
    assert!(duration.is_some_and(|d| (d - 2.0).abs() < 0.1), "{duration:?}");
    // The controls heard the playhead move and the first frame.
    assert!(
        seen.iter()
            .any(|e| matches!(e, HostEvent::State(s) if s.has_picture && s.position.is_some()))
    );
}

#[test]
fn a_quit_reports_the_end_and_the_close_once_and_refuses_what_follows() {
    let rig = rig();
    let one = PlaybackId::new(7);
    rig.player.apply(one, &PlayerOp::Open { fullscreen: false, speed: None, volume: None });
    rig.player.apply(
        one,
        &PlayerOp::Load { url: PATTERN.replace("duration=2", "duration=30"), options: vec![] },
    );
    rig.until(|e| *e == report(one, PlayerReport::FileLoaded));

    rig.player.apply(one, &PlayerOp::Quit);
    let mut seen = rig.quiet_for(Duration::from_millis(600));
    let reports: Vec<_> = seen
        .iter()
        .filter(|e| matches!(e, HostEvent::Report { report, .. } if !matches!(report, PlayerReport::Property { .. })))
        .cloned()
        .collect();
    assert_eq!(
        reports,
        [
            report(one, PlayerReport::Ended { reason: PlayerEnd::Quit }),
            report(one, PlayerReport::Closed)
        ],
        "mpv's own end of the stopped file is not said: {seen:#?}"
    );
    assert!(seen.contains(&HostEvent::Closed));

    // What crosses the close is let go, and the engine hears Closed no more than once.
    rig.player.apply(one, &PlayerOp::Seek { seconds: 5.0, absolute: true });
    rig.player.apply(one, &PlayerOp::Close);
    seen = rig.quiet_for(Duration::from_millis(300));
    assert!(!seen.iter().any(|e| matches!(e, HostEvent::Report { .. })), "{seen:#?}");

    // A newer playback opens it again.
    let two = PlaybackId::new(8);
    open_and_load(&rig, two);
    rig.until(|e| *e == report(two, PlayerReport::FileLoaded));
}

#[test]
fn a_property_set_and_a_seek_land() {
    let rig = rig();
    let one = PlaybackId::new(3);
    rig.player.apply(one, &PlayerOp::Open { fullscreen: false, speed: None, volume: None });
    rig.player.apply(
        one,
        &PlayerOp::Load { url: PATTERN.replace("duration=2", "duration=30"), options: vec![] },
    );
    rig.until(|e| *e == report(one, PlayerReport::FileLoaded));
    rig.player.apply(one, &PlayerOp::Cycle { property: "pause".into() });
    rig.until(|e| matches!(e, HostEvent::State(s) if s.paused));
    rig.player.apply(one, &PlayerOp::Seek { seconds: 20.0, absolute: true });
    rig.until(|e| matches!(e, HostEvent::State(s) if s.position.is_some_and(|p| (p - 20.0).abs() < 0.5)));
    assert_eq!(rig.player.mpv().get("pause"), Some(serde_json::Value::Bool(true)));

    rig.player.apply(one, &PlayerOp::RestateChapters);
    let seen = rig.until(|e| matches!(e, HostEvent::Report { report: PlayerReport::Property { name, .. }, .. } if name == "chapter-list"));
    assert!(
        matches!(seen.last(), Some(HostEvent::Report { report: PlayerReport::Property { json, .. }, .. }) if json == "[]")
    );
}
